{"implementation":"def solve(case):
    import math

    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    data = case.get("payload", case)
    if not isinstance(data, dict):
        raise ValueError("payload must be an object")

    required = ("nodes", "core_distance", "distances")
    for name in required:
        if name not in data:
            raise ValueError("missing required field: " + name)

    nodes = data["nodes"]
    core_distance = data["core_distance"]
    distances = data["distances"]

    if not isinstance(nodes, list) or not nodes:
        raise ValueError("nodes must be a non-empty list")
    if any(not isinstance(node, str) for node in nodes):
        raise ValueError("node IDs must be strings")
    if len(set(nodes)) != len(nodes):
        raise ValueError("node IDs must be unique")
    if not isinstance(core_distance, dict):
        raise ValueError("core_distance must be an object")
    if set(core_distance) != set(nodes):
        raise ValueError("core_distance must contain exactly the nodes")
    if not isinstance(distances, list):
        raise ValueError("distances must be a list")

    def finite_number(value):
        return isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value)

    for node in nodes:
        if not finite_number(core_distance[node]) or core_distance[node] < 0:
            raise ValueError("core distances must be finite non-negative numbers")

    node_set = set(nodes)
    seen = set()
    edges = []
    for item in distances:
        if not isinstance(item, (list, tuple)) or len(item) != 3:
            raise ValueError("each distance must be a three-item sequence")
        left, right, distance = item
        if left not in node_set or right not in node_set or left == right:
            raise ValueError("distance endpoints must be distinct registered nodes")
        if not finite_number(distance) or distance < 0:
            raise ValueError("distances must be finite non-negative numbers")
        if right < left:
            left, right = right, left
        key = (left, right)
        if key in seen:
            raise ValueError("duplicate undirected distance edge")
        seen.add(key)
        weight = max(core_distance[left], core_distance[right], distance)
        edges.append((weight, left, right))

    edges.sort(key=lambda edge: (edge[0], edge[1], edge[2]))

    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(node):
        while parent[node] != node:
            parent[node] = parent[parent[node]]
            node = parent[node]
        return node

    def union(left, right):
        left_root = find(left)
        right_root = find(right)
        if left_root == right_root:
            return False
        if rank[left_root] < rank[right_root]:
            left_root, right_root = right_root, left_root
        parent[right_root] = left_root
        if rank[left_root] == rank[right_root]:
            rank[left_root] += 1
        return True

    selected = []
    total_weight = 0
    for weight, left, right in edges:
        if union(left, right):
            selected.append([left, right, weight])
            total_weight += weight
            if len(selected) == len(nodes) - 1:
                break

    if len(selected) != len(nodes) - 1:
        raise ValueError("distance graph is disconnected")

    return {"mst_edges": selected, "total_weight": total_weight}
